package com.example.minicommerce.notification.infrastructure;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="notifications")public class NotificationEntity{@Id private UUID id;@Column(name="user_id",nullable=false)private Long userId;@Column(nullable=false,length=100)private String type;@Column(nullable=false,length=500)private String message;@Column(nullable=false)private boolean unread;@Column(name="created_at",nullable=false)private Instant createdAt;protected NotificationEntity(){}public NotificationEntity(Long u,String t,String m,Instant n){id=UUID.randomUUID();userId=u;type=t;message=m;unread=true;createdAt=n;}public UUID getId(){return id;}public Long getUserId(){return userId;}public String getMessage(){return message;}public boolean isUnread(){return unread;}public Instant getCreatedAt(){return createdAt;}}
